  'co.singular': ['T es singular: no define un cambio de coordenadas.', 'T is singular: it does not define a change of coordinates.', 'T é singular: não define uma mudança de coordenadas.', 'T est singulière : elle ne définit pas un changement de coordonnées.', 'T è singolare: non definisce un cambio di coordinate.', 'T ist singulär: kein gültiger Koordinatenwechsel.'],
  'co.invariants': ['Invariantes', 'Invariants', 'Invariantes', 'Invariants', 'Invarianti', 'Invarianten'],
